import{_ as a,c as t,o as r,ag as i}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Priority queues and a small scheduler","description":"","frontmatter":{},"headers":[],"relativePath":"cs-foundations/priority-queues.md","filePath":"cs-foundations/priority-queues.md"}'),o={name:"cs-foundations/priority-queues.md"};function n(s,e,d,l,c,p){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="priority-queues-and-a-small-scheduler" tabindex="-1">Priority queues and a small scheduler <a class="header-anchor" href="#priority-queues-and-a-small-scheduler" aria-label="Permalink to “Priority queues and a small scheduler”">​</a></h1><p>FIFO chooses the oldest admitted item. A <strong>priority queue</strong> chooses the item with the smallest key here; other designs choose the largest. A note-check scheduler can prioritize a broken required reference ahead of an optional cosmetic check, without sorting its entire pending list after every arrival.</p><p>This is local algorithmic scheduling, not an operating-system CPU scheduler or a durable job queue. It supplies no timer, concurrency limit, retries, persistence or authorization.</p><h2 id="array-representation-and-invariant" tabindex="-1"><span class="hub-section-number">1 </span>Array representation and invariant <a class="header-anchor" href="#array-representation-and-invariant" aria-label="Permalink to “1 Array representation and invariant”">​</a></h2><p>A zero-indexed binary min-heap stores a complete binary tree in an array. For index <code>i</code>, children are <code>2i+1</code> and <code>2i+2</code>; for <code>i&gt;0</code>, parent is <code>floor((i−1)/2)</code>. No pointer nodes are required, and the height is O(log(n+1)).</p><p>The invariant is <strong>parent ≤ child</strong>, ordered lexicographically by <code>(priority, admissionSequence)</code>. Therefore the root is no greater than any descendant and is a valid minimum. Siblings need not be sorted. Two equal-priority jobs leave in admission order because the sequence breaks ties; this is an explicit policy, not an automatic heap property.</p><h2 id="worked-insertion-and-removal" tabindex="-1"><span class="hub-section-number">2 </span>Worked insertion and removal <a class="header-anchor" href="#worked-insertion-and-removal" aria-label="Permalink to “2 Worked insertion and removal”">​</a></h2><p>Start with priorities <code>[2, 5, 4]</code>. Append priority 1 at index 3: only its ancestor path can violate the heap invariant. Swap with parent 5, then parent 2, yielding <code>[1, 2, 4, 5]</code>.</p><p>Pop removes root 1 and moves the last value 5 to root: <code>[5, 2, 4]</code>. Swap with the <strong>smaller</strong> child 2 to obtain <code>[2, 5, 4]</code>. Choosing the larger child would leave the smaller child above-order and break the invariant.</p><table tabindex="0"><thead><tr><th>Operation</th><th>Why correct</th><th>Conventional model cost</th></tr></thead><tbody><tr><td>Push</td><td>Only the appended node/ancestor path may violate order; swapping with its parent restores the lower edge while moving the possible violation upward</td><td>O(log(n+1)) comparisons/swaps</td></tr><tr><td>Pop</td><td>Subtrees remain heaps after root replacement; promote the smaller child and move the possible violation downward until none remains</td><td>O(log(n+1)) comparisons/swaps</td></tr><tr><td>Peek</td><td>Every descendant is at least its parent, hence at least the root</td><td>O(1)</td></tr><tr><td>Arbitrary lookup</td><td>No sibling or global array order permits binary search</td><td>O(n) scan</td></tr></tbody></table><p>Bottom-up heap construction can be O(n): most nodes are near the leaves and move only a few levels. Repeated push builds in O(n log n) worst-case comparisons instead. The source uses repeated push only; it does not claim a linear build implementation.</p><h2 id="reference-contract-and-limits" tabindex="-1"><span class="hub-section-number">3 </span>Reference contract and limits <a class="header-anchor" href="#reference-contract-and-limits" aria-label="Permalink to “3 Reference contract and limits”">​</a></h2><p><a href="./../workbench/cs-foundations/collections.html#stable-min-priority-queue">Canonical heap source</a> accepts finite numeric priorities, including negative values. Smaller means sooner. Payloads are opaque and not mutated. Full push, invalid priority and empty peek/pop reject without removing a valid job. An admission sequence must remain an exact safe integer; exhaustion rejects rather than silently losing tie order.</p><p>Array append can itself resize: the comparison/swap bounds above plus amortized-array allocation apply to the source. A single actual push is not guaranteed O(log n) latency by ECMAScript. Capacity bounds retained entry count, not the bytes reachable from payloads. <code>snapshot()</code> costs O(n), is for verification, and returns priority/sequence copies.</p><p>Changing a queued object&#39;s field does not change its captured priority. There is no decrease-key, cancellation or removal-by-ID operation; implement those with a deliberate index/ownership policy if required. Low-priority jobs can starve if high-priority arrivals never stop. FIFO ties do not solve starvation across different priorities. For a finite practice run, stop admission and drain all jobs; real services may require aging/fairness policy.</p><p><a href="./../practice/cs-foundations/dependency-explorer.html#cs-p06-priority-scheduler">Separate scheduler exercise</a> · <a href="./coverage-map.html">Course coverage</a></p>',16)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
